//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Web.Shared.dll
using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.Globalization;
using System.Net;
using System.Net.Http;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Satisfactory 1.0+ has two query surfaces, both on the GAME port:
// - the HTTPS API (TCP, self-signed certificate). HealthCheck needs no token. The session details need one,
//   which PasswordlessLogin hands out unless a player (client) password is set.
// - the Lightweight Query API (UDP). It needs no auth and is the only place that reports the server NAME
//   (set in-game when claiming, or in the Server Manager). The panel copies the query's Name into the
//   service name, so returning it here is how an in-game rename reaches the panel.
// Every UDP poll lands on the game's own socket and the server logs a "LogNet: NotifyAcceptingConnection" line
// for it, so the name is polled at most every NamePollInterval and reused in between. The cache lives in the
// monitor's AppDomain data (keyed per service, address and port), as BCL types only, so it survives the script
// being recompiled.
// The monitor gives the whole script 10 seconds; the timeouts below keep the worst case under that.
string address = Variables.Parse<string>("Address", null);
if (string.IsNullOrEmpty(address))
    address = ThisService.IPAddress;
int port = ThisService.GamePort;
string url = $"https://{address}:{port}/api/v1";

static JsonElement CallApi(HttpClient client, string apiUrl, string function, object data, string token, out int status)
{
    var request = new HttpRequestMessage(HttpMethod.Post, apiUrl)
    {
        Content = new StringContent(JsonSerializer.Serialize(new { function, data }), Encoding.UTF8, "application/json")
    };
    if (!string.IsNullOrEmpty(token))
        request.Headers.TryAddWithoutValidation("Authorization", "Bearer " + token);
    using var response = client.Send(request);
    status = (int)response.StatusCode;
    string body = response.Content.ReadAsStringAsync().GetAwaiter().GetResult();
    return string.IsNullOrWhiteSpace(body) ? default : JsonDocument.Parse(body).RootElement.Clone();
}

static string Str(JsonElement e, string name, string fallback = "") =>
    e.ValueKind == JsonValueKind.Object && e.TryGetProperty(name, out var v)
        ? (v.ValueKind == JsonValueKind.String ? v.GetString() : v.ToString())
        : fallback;

// Lightweight Query API, PollServerState (protocol version 1). Request: magic 0xF6D5 (uint16), message type 0,
// protocol version 1, a uint64 cookie, terminator 0x01. Response (type 1) echoes the cookie, then: server state
// (uint8), changelist (uint32), flags (uint64), sub-state count (uint8) + 3 bytes per sub-state, name length
// (uint16) + UTF-8 name, terminator. All little-endian. Returns false on no answer or a malformed one.
static bool PollServerName(string host, int udpPort, out string serverName)
{
    serverName = null;
    ulong cookie = BinaryPrimitives.ReadUInt64LittleEndian(RandomNumberGenerator.GetBytes(8));
    var request = new byte[13];
    BinaryPrimitives.WriteUInt16LittleEndian(request.AsSpan(0), 0xF6D5);
    request[2] = 0;
    request[3] = 1;
    BinaryPrimitives.WriteUInt64LittleEndian(request.AsSpan(4), cookie);
    request[12] = 1;

    using var udp = new UdpClient(AddressFamily.InterNetwork);
    udp.Client.ReceiveTimeout = 1500;
    udp.Send(request, request.Length, host, udpPort);
    var deadline = DateTime.UtcNow.AddMilliseconds(1500);
    while (DateTime.UtcNow < deadline)
    {
        byte[] data;
        try
        {
            var from = new IPEndPoint(IPAddress.Any, 0);
            data = udp.Receive(ref from);
        }
        catch (SocketException)
        {
            return false;
        }

        // Skip anything that is not the answer to this request (a late reply to an earlier poll, a stray packet).
        const int fixedPart = 2 + 1 + 1 + 8 + 1 + 4 + 8 + 1;
        if (data.Length < fixedPart + 2 ||
            BinaryPrimitives.ReadUInt16LittleEndian(data) != 0xF6D5 || data[2] != 1 ||
            BinaryPrimitives.ReadUInt64LittleEndian(data.AsSpan(4)) != cookie)
            continue;

        int offset = fixedPart + data[fixedPart - 1] * 3;
        if (data.Length < offset + 2)
            return false;
        int nameLength = BinaryPrimitives.ReadUInt16LittleEndian(data.AsSpan(offset));
        offset += 2;
        if (data.Length < offset + nameLength)
            return false;
        serverName = Encoding.UTF8.GetString(data, offset, nameLength).Trim();
        return true;
    }
    return false;
}

// Roslyn script mode rejects a top-level `using var`, hence the try/finally.
var http = new HttpClient(new HttpClientHandler { ServerCertificateCustomValidationCallback = (m, c, ch, e) => true })
{
    Timeout = TimeSpan.FromSeconds(2.5)
};
try
{
    // A failed health check throws, so the monitor reports the service offline.
    var health = CallApi(http, url, "HealthCheck", new { clientCustomData = "" }, null, out int healthStatus);
    if (healthStatus != 200)
        throw new Exception($"HealthCheck returned HTTP {healthStatus}");

    var rules = new Dictionary<string, string> { ["Health"] = Str(health.GetProperty("data"), "health", "unknown") };

    // An unclaimed server has no name yet, and a lost UDP reply must not rename the service, so either case
    // keeps the last known name, or the panel's current one. A failed poll is retried after a minute.
    var namePollInterval = TimeSpan.FromMinutes(5);
    string cacheKey = $"TCAdmin.Satisfactory.ServerName:{ThisService.ServiceId}:{address}:{port}";
    var cached = AppDomain.CurrentDomain.GetData(cacheKey) as Tuple<DateTime, string>;
    string name = string.IsNullOrEmpty(cached?.Item2) ? ThisService.Name : cached.Item2;
    if (cached == null || DateTime.UtcNow >= cached.Item1)
    {
        bool polled = PollServerName(address, port, out string serverName);
        if (polled && !string.IsNullOrEmpty(serverName))
            name = serverName;
        var nextPoll = DateTime.UtcNow + (polled ? namePollInterval : TimeSpan.FromMinutes(1));
        AppDomain.CurrentDomain.SetData(cacheKey, Tuple.Create(nextPoll, polled ? serverName : cached?.Item2));
    }

    int numPlayers = 0;
    int maxPlayers = ThisService.Slots;

    var login = CallApi(http, url, "PasswordlessLogin", new { MinimumPrivilegeLevel = "Client" }, null, out int loginStatus);
    if (loginStatus == 200)
    {
        rules["Player Password"] = "No";
        string token = Str(login.GetProperty("data"), "authenticationToken");
        var state = CallApi(http, url, "QueryServerState", new { }, token, out int stateStatus);
        if (stateStatus == 200)
        {
            var gs = state.GetProperty("data").GetProperty("serverGameState");
            rules["Session"] = Str(gs, "activeSessionName");
            numPlayers = gs.GetProperty("numConnectedPlayers").GetInt32();
            maxPlayers = gs.GetProperty("playerLimit").GetInt32();

            // gamePhase looks like "/Script/FactoryGame.FGGamePhase'GP_Project_Assembly_Phase_2'"
            string phase = Str(gs, "gamePhase", "None");
            int phaseIndex = phase.LastIndexOf("Phase_", StringComparison.Ordinal);
            if (phaseIndex >= 0)
                phase = "Phase " + phase.Substring(phaseIndex + 6).Trim('\'', '"');
            rules["Phase"] = phase;
            rules["Tech Tier"] = Str(gs, "techTier", "0");
            rules["Running"] = Str(gs, "isGameRunning", "false");
            rules["Paused"] = Str(gs, "isGamePaused", "false");
            rules["Tick Rate"] = Math.Round(gs.GetProperty("averageTickRate").GetDouble(), 1)
                .ToString(CultureInfo.InvariantCulture);
        }
    }
    else if (Str(login, "errorCode") == "passwordless_login_not_possible")
    {
        rules["Player Password"] = "Yes";
    }

    Globals.ReturnValue = new GameQueryResponse
    {
        Status = "online",
        Hostname = $"{address}:{port}",
        Name = name,
        GameType = "Satisfactory",
        Map = "Satisfactory",
        NumPlayers = numPlayers,
        MaxPlayers = maxPlayers,
        Rules = rules,
    };
}
finally
{
    http.Dispose();
}
